import{_ as a,o as t,c as o,a2 as n}from"./chunks/framework.CjAa9jTu.js";const i="/unit_devlab_cortex_m_examples/py32f003/pinout-es.png",s="/unit_devlab_cortex_m_examples/py32f003/topologia.png",r="/unit_devlab_cortex_m_examples/py32f003/dimensiones.png",b=JSON.parse('{"title":"Pinout y esquemático","description":"","frontmatter":{},"headers":[],"relativePath":"py32f003-getting-started/03_pinout.md","filePath":"py32f003-getting-started/03_pinout.md"}'),d={name:"py32f003-getting-started/03_pinout.md"};function l(c,e,p,u,m,_){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="pinout-y-esquematico" tabindex="-1">Pinout y esquemático <a class="header-anchor" href="#pinout-y-esquematico" aria-label="Permalink to &quot;Pinout y esquemático&quot;">​</a></h1><h2 id="distribucion-de-pines" tabindex="-1">Distribución de pines <a class="header-anchor" href="#distribucion-de-pines" aria-label="Permalink to &quot;Distribución de pines&quot;">​</a></h2><p><img src="'+i+'" alt="Pinout de DevLab PY32F003 en español, vistas superior e inferior"></p><p><a href="/unit_devlab_cortex_m_examples/py32f003/pinout-es.pdf">Descargar pinout en español (PDF)</a> · <a href="/unit_devlab_cortex_m_examples/py32f003/esquematico.pdf">Abrir esquemático (PDF)</a></p><h2 id="pines-utilizados-en-los-ejemplos" tabindex="-1">Pines utilizados en los ejemplos <a class="header-anchor" href="#pines-utilizados-en-los-ejemplos" aria-label="Permalink to &quot;Pines utilizados en los ejemplos&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Señal de la placa</th><th>Uso en el taller</th><th>Observación</th></tr></thead><tbody><tr><td>PB5</td><td>LED de usuario</td><td>Comparte la función MOSI; comprobar LED Enable</td></tr><tr><td>PA0</td><td>TX de <code>Serial</code></td><td>Conectar a RX del adaptador USB-UART</td></tr><tr><td>PA1</td><td>RX de <code>Serial</code></td><td>Conectar a TX del adaptador USB-UART</td></tr><tr><td>PA2</td><td>Pulsador externo o ADC_IN2</td><td>Usar un solo ejercicio a la vez</td></tr><tr><td>PA13 / PA10</td><td>SWDIO / SDA</td><td>Misma conexión física en este encapsulado</td></tr><tr><td>PA14 / PB6</td><td>SWCLK / SCL</td><td>Misma conexión física en este encapsulado</td></tr><tr><td>PB0 / PF2-NRST</td><td>Reinicio</td><td>Mantener la función de reset durante el taller</td></tr><tr><td>GND</td><td>Tierra</td><td>Referencia común para placa, programador y accesorios</td></tr></tbody></table><p>Los nombres <code>PA0</code>, <code>PA1</code>, <code>PA2</code> y <code>PB5</code> son los identificadores usados en el código Arduino. Los números de un Arduino UNO no describen estas conexiones.</p><div class="warning custom-block"><p class="custom-block-title">Pines compartidos</p><p>PA10/PB6 y PA13/PA14 corresponden a dos conexiones físicas compartidas del DFN8. Los dos conectores de cuatro pines tampoco son buses independientes. No conectes un periférico I²C mientras programas por SWD. Consulta la <a href="./33_i2c">guía I²C</a> antes de reutilizar esas líneas.</p></div><h2 id="alimentacion" tabindex="-1">Alimentación <a class="header-anchor" href="#alimentacion" aria-label="Permalink to &quot;Alimentación&quot;">​</a></h2><p>El esquema distingue la entrada <strong>5V</strong>, la salida regulada <strong>3V3</strong> y <strong>VCC</strong>, que alimenta al microcontrolador. El selector determina si VCC se une a 3.3 V o a 5 V. La estación del taller se prepara con VCC a <strong>3.3 V</strong>.</p><p>Los conectores de cuatro pines llevan <strong>GND, VCC, SWDIO/SDA y SWCLK/SCL</strong>. Identifica cada señal en la serigrafía: la orientación de la placa y del cable cambia el orden que ves. El formato JST no garantiza compatibilidad eléctrica entre cualquier par de dispositivos.</p><h2 id="led-y-boton-de-la-placa" tabindex="-1">LED y botón de la placa <a class="header-anchor" href="#led-y-boton-de-la-placa" aria-label="Permalink to &quot;LED y botón de la placa&quot;">​</a></h2><p>El LED de usuario se conecta a <strong>PB5</strong> y enciende con <code>HIGH</code>. En las placas con puente <strong>LED Enable</strong>, éste debe estar cerrado para completar el circuito. El LED de alimentación sólo indica presencia de tensión.</p><p>El botón integrado es <strong>RESET</strong>, por lo que reinicia la ejecución cuando la función NRST está habilitada. Para practicar <code>digitalRead()</code> utiliza un <a href="./../examples/lab02-gpio">pulsador externo en PA2</a>.</p><h2 id="topologia-y-dimensiones" tabindex="-1">Topología y dimensiones <a class="header-anchor" href="#topologia-y-dimensiones" aria-label="Permalink to &quot;Topología y dimensiones&quot;">​</a></h2><p><img src="'+s+'" alt="Topología de la placa DevLab PY32F003"></p><p><img src="'+r+'" alt="Dimensiones de la placa DevLab PY32F003"></p><p><strong>Siguiente paso:</strong> <a href="./04_swd">Programación SWD</a>.</p>',18)])])}const h=a(d,[["render",l]]);export{b as __pageData,h as default};
